-- P14 The Memory Bank - Stage 3
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Memory Bank - Storage Bay Survey","dataPayload":"STORAGE BAY: twelve sealed cells in two banks. Each cell door carries a two-part plate: a SUBJECT CODE (S-00 through S-05, some repeated) and a small DIRECTION arrow. Three arrows point inward (store); nine point outward (recall). The cells are wired point to point to the reading console; no cell shares a line with another.","visualType":"observation","whatTheySee":"A bank of sealed storage cells; every plate names a subject and a direction.","taskPrompt":"Record what each cell plate names, and note the wiring.","intermediateOutput":"Twelve cells; each plate carries a subject code and a direction arrow."},"analyst":{"role":"ANALYST","screenTitle":"Key-Class Glossary and Index Card","dataPayload":"INDEX CARD: the Memory Bank index is not a list of contents. Each line is a KEY: the first field names WHOSE store (a subject); the second names WHICH WAY the trace runs (recall or store). The glossary defines the vault key classes by the fields they carry: a SCALAR key carries one value and no subject; a MATRIX key carries two subjects and no direction; the third class carries BOTH an address (which subject) and a direction (which way).","visualType":"document-forensics","whatTheySee":"An index whose keys pair a subject with a direction, beside a glossary of key classes.","taskPrompt":"Match the index key against the glossary: which class names a key that carries both a subject and a direction?","intermediateOutput":"The index uses the class defined as address plus direction."},"operator":{"role":"OPERATOR","screenTitle":"Memory Bank Access Register","dataPayload":"ACCESS REGISTER: the Memory Bank holds no copies. Every registered cell is a LIVE segment belonging to one subject; the register states the vault was never permitted to keep a duplicate. The index is filed under a key class, and the register keeps that class name in a sealed field the Operator alone may open.","visualType":"meta","whatTheySee":"An access register that classifies the vault index by key class.","taskPrompt":"Submit the key class under which the Memory Bank index is filed.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The Memory Bank access register: no duplicates are held, every cell is a live subject store, and the index is filed under a sealed key class.","operatorTaskDescription":"Compare the register custody rule (live stores, never a backup) with the key-class glossary, then submit the class the register seals."},"coordinationChain":{"observerProduces":"Observer reports that each cell plate names a subject and a direction.","analystTransforms":"Analyst matches the index key to the glossary class carrying both an address and a direction.","operatorExecutes":"Operator opens the sealed register field and submits the key class."},"hints":["The question is what the KEY names, not what the cells store.","Each index key has two fields: whose store, and which way the trace runs.","A value that carries both an address and a direction is a named class in the glossary - give that class."],"narrativeObjective":"Classify the Memory Bank index by the key class it actually uses.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"VECTOR","validationMethod":"exact","fullSolution":"The index key pairs a subject (an address) with a direction (recall or store). The glossary class for a quantity that carries both an address and a direction is the class the register seals the index under, which makes the key class VECTOR."}',
  metadata = '{"type":"MEMORY","difficulty":3,"time":"6m","storyReveal":"The Memory Bank is not a backup. It holds live segments keyed by subject and direction - one index, no copies - and that index is filed under a containment classification rather than a name. The vault is where a subject is held, not mirrored.","locationClue":{"format":"Symbol","clueText":"LINA''S NOTE: \"The first condition-mark is cut at the library entrance. Read it, then follow the wall.\"","solution":"Library Entrance First Condition-Mark","nextPhysicalLocation":"[LIBRARY] - Entrance Symbol","nextQrNode":"QR-NODE-17","explanation":"Directs teams from the memory lab to the condition-mark at the library entrance."},"evidenceUnlocked":{"id":"EVID-P14","category":"Visual","title":"Library Entrance Condition-Mark - Origin","state":"RECOVERED","timestamp":"Stage 3","source":"Library entrance","content":"A carved condition-mark above the library entrance. It logs ORIGIN: the condition recorded when a subject was first entered into the programme."},"whyTeamworkMatters":"Only the cells show each store is live and keyed to a subject; only the glossary defines the key classes; only the register seals which class the index is filed under.","feeds":"M02"}'
WHERE code = 'P14';

-- P15 The Cipher Wheel - Stage 3
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Cipher Wheel - Physical Inspection","dataPayload":"WALL DEVICE: a brass dial fixed to the stone. Seven radial spokes, each ending in one of the seven condition-marks; a single fixed pointer at the top. There is no ring of letters and no inner ring to rotate against, so the dial cannot step through an alphabet. The centre boss carries an accession stamp, worn smooth at the edges.","visualType":"observation","whatTheySee":"A seven-spoke dial with a fixed pointer, no letter ring, and a stamped centre boss.","taskPrompt":"Record the number of positions, whether there is an alphabet ring, and the state of the centre boss.","intermediateOutput":"Seven positions, fixed pointer, no letter ring; centre boss stamped."},"analyst":{"role":"ANALYST","screenTitle":"Dial Reference and Classification Scheme","dataPayload":"REFERENCE: a true substitution wheel carries twenty-six letters on an outer ring and a steppable inner ring; it is turned to a key and read off. This device has seven positions and a fixed pointer. Seven positions match the seven containment conditions, not an alphabet. The dial is the archive''s condition selector: an ordered classification scheme.","visualType":"document-forensics","whatTheySee":"A reference contrasting a twenty-six-letter cipher wheel with a seven-position classification dial.","taskPrompt":"Decide from the reference whether the device enciphers text or classifies records.","intermediateOutput":"A seven-position classification dial, not a cipher."},"operator":{"role":"OPERATOR","screenTitle":"Accession and Custody Record","dataPayload":"CUSTODY STAMP: the accession stamp on the centre boss, read in the archive''s own notation, names BINDER THIRTY-FOUR, SHELF TWO, FILE FIVE. It is a charging mark: the object entered the record as a filed exhibit, never as a key. Submit the case-file reference the stamp names.","visualType":"meta","whatTheySee":"A custody record whose stamp names a case-file address in the archive''s own notation.","taskPrompt":"Submit the case-file reference the accession stamp names.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The accession and custody record: the centre boss is a charging stamp naming a case-file address, and the object was filed as an exhibit rather than issued as a key.","operatorTaskDescription":"Read the stamp in the archive''s own notation, compose the case-file reference from binder, shelf and file, and submit it."},"coordinationChain":{"observerProduces":"Observer reports seven positions, a fixed pointer, no alphabet ring, and a stamped centre boss.","analystTransforms":"Analyst shows the device classifies seven conditions rather than enciphering an alphabet.","operatorExecutes":"Operator composes the case-file reference from the accession stamp and submits it."},"hints":["Ask what a cipher wheel must have that this device does not.","Count the positions and compare them with the seven condition-marks.","A seven-position dial is a classifier; the only remaining number is the case-file reference stamped on its boss."],"narrativeObjective":"Determine what the wall dial is, and recover the reference its stamp names.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"3425","validationMethod":"exact","fullSolution":"The dial has seven positions, a fixed pointer and no alphabet ring: a classification dial, not a cipher. Its charging stamp names a case-file address which composes to the reference 3425."}',
  metadata = '{"type":"CIPHER","difficulty":3,"time":"7m","storyReveal":"The wall dial enciphers nothing. It has seven positions - the seven containment conditions - and its centre is a Bureau charging stamp. The team has been reading a classification dial as if it were a key.","locationClue":{"format":"Symbol","clueText":"LINA''S NOTE: \"The next condition-mark waits at the library book return. Read it where the returns stack.\"","solution":"Library Book Return Condition-Mark","nextPhysicalLocation":"[LIBRARY] - Book Return Symbol","nextQrNode":"QR-NODE-18","explanation":"Directs teams from the entrance wall to the condition-mark at the library book return."},"evidenceUnlocked":{"id":"EVID-P15","category":"Visual","title":"Library Book Return Condition-Mark - Connection","state":"RECOVERED","timestamp":"Stage 3","source":"Library book return","content":"A carved condition-mark where the returns stack. It logs CONNECTION: the condition recorded for a subject linked into the programme lattice."},"whyTeamworkMatters":"Only the dial shows seven positions and no alphabet; only the reference defines a classification dial; only the custody stamp names the case-file reference.","feeds":"P14"}'
WHERE code = 'P15';

-- P16 The Auditorium - Stage 3
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Auditorium Seating Plan - Section B","dataPayload":"MAIN AUDITORIUM: the archived seating plan, Section B, rows one through ten. Each row is cut by a centre aisle into an inboard bank of EIGHT seats and an outboard bank of SEVEN. The two banks repeat unchanged down every row, and the plan does not mark who sat where.","visualType":"observation","whatTheySee":"A seating plan whose rows are each split by a centre aisle into two fixed banks.","taskPrompt":"Record the seat banks in a single row of Section B.","intermediateOutput":"One row holds the same two banks as every other row."},"analyst":{"role":"ANALYST","screenTitle":"Attendance Roll - Margin Tally","dataPayload":"ATTENDANCE ROLL: this is a seating roll, not an events book. Its margin carries the room''s own after-the-fact tally of each row, written out in letters, and that tally repeats unchanged row after row. An occupancy figure would change with every event; this figure never does, because it counts the fixed seating, not the attendance.","visualType":"document-forensics","whatTheySee":"A seating roll whose margin tallies each row in letters and never varies.","taskPrompt":"Use the roll margin to decide whether the figure is a seating count or an occupancy.","intermediateOutput":"The roll tally is a fixed seating count, not an occupancy."},"operator":{"role":"OPERATOR","screenTitle":"Facilities Register - Certified Allocation","dataPayload":"FACILITIES REGISTER: the room certified seating allocation is filed in the estates register under the row total. The register will accept the row total as a number. Submit it.","visualType":"meta","whatTheySee":"An estates register that files the room seating allocation by row total.","taskPrompt":"Submit the number of seats in one Section B row.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The facilities register, which files the room certified seating allocation under the row total and accepts that total as a number.","operatorTaskDescription":"Combine the two seat banks the Observer recorded, confirm the total against the roll margin, and submit the row total."},"coordinationChain":{"observerProduces":"Observer records the two seat banks that make up one Section B row.","analystTransforms":"Analyst shows the roll margin tallies the fixed seating and never varies.","operatorExecutes":"Operator sums the row banks against the certified allocation and submits the row total."},"hints":["Decide first whether you are counting fixed seats or people.","The roll margin tallies each row and never changes; an occupancy would change with every event.","Add the two fixed banks that the centre aisle divides in a single row."],"narrativeObjective":"Classify the auditorium figure as fixed seating and recover the row total.","roleDependencyLevel":"D2"}',
  answer_metadata = '{"acceptedAnswer":"15","validationMethod":"exact","fullSolution":"The plan splits every row into a fixed inboard bank and a fixed outboard bank, and the roll margin tallies the same total row after row, so the figure is fixed seating. The row total is 15."}',
  metadata = '{"type":"OBSERVATION","difficulty":3,"time":"6m","storyReveal":"The auditorium figure is fixed seating, not attendance and not an evacuation figure: the roll margin tallies the same number row after row. The room was surveyed for capacity, not for a crowd.","locationClue":{"format":"Poetic","clueText":"LINA''S NOTE: \"Behind the auditorium stage the next condition-mark is cut in wood.\"","solution":"Auditorium Stage Condition-Mark","nextPhysicalLocation":"[SCIENCE BUILDING] - Stage Fourth Glyph","nextQrNode":"QR-NODE-19","explanation":"Directs teams from the seating plan to the condition-mark behind the stage."},"evidenceUnlocked":{"id":"EVID-P16","category":"Visual","title":"Auditorium Stage Condition-Mark - Structure","state":"RECOVERED","timestamp":"Stage 3","source":"Behind auditorium stage","content":"A wooden condition-mark behind the stage. It logs STRUCTURE: the condition recorded for a subject assigned a fixed place in the lattice."},"whyTeamworkMatters":"Only the plan shows the row banks; only the roll margin proves the figure is fixed seating; only the estates register files the certified allocation.","feeds":"P15"}'
WHERE code = 'P16';

-- P17 The Audio Log - Stage 3
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Audio Log - Spectrum Survey","dataPayload":"AUDIO LOG: a single-channel recording. One sharp onset, then a long decay carrying evenly spaced returns; there is no voiced pitch and no steady tone. The returns keep a fixed spacing long after the sound has stopped, and they thin out rather than repeat forever.","visualType":"audio","whatTheySee":"A spectrum with a single onset and a decaying train of returns, no voice and no held note.","taskPrompt":"Record whether there is speech, a sustained tone, or something else.","intermediateOutput":"Not speech and not a tone: one onset then decaying returns."},"analyst":{"role":"ANALYST","screenTitle":"Recording Class Register","dataPayload":"RECORDING CLASSES: the archive files room recordings under three classes. A VOICED record carries sustained speech. A STEADY record carries a tone held flat. The third class covers a record that is the room answering a single impulse: one onset, then the chamber''s own decaying returns. Only the third class fits this log: it is neither a person nor a note, but the room''s reply.","visualType":"document-forensics","whatTheySee":"A class register defining voiced, steady and room-reply recordings.","taskPrompt":"Match the log against the classes and name the class it belongs to.","intermediateOutput":"The log is the class where the room answers one sound."},"operator":{"role":"OPERATOR","screenTitle":"Audio Log Custody Field","dataPayload":"CUSTODY FIELD: the log class field stays sealed until the team names what the recording actually is. Submit the archive class for a record that is the room''s own answer to one sound.","visualType":"meta","whatTheySee":"A sealed class field on the audio log.","taskPrompt":"Submit the archive class for this recording.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The audio log custody field, sealed until the team names the class the recording belongs to under the archive recording scheme.","operatorTaskDescription":"Match the log behaviour (one onset, decaying returns, no voice, no tone) against the class register and submit the class name."},"coordinationChain":{"observerProduces":"Observer reports one onset and a decaying train of returns, with no speech and no held tone.","analystTransforms":"Analyst matches the log to the class that is the room answering a single impulse.","operatorExecutes":"Operator opens the sealed field and submits the class name."},"hints":["Rule out what the log is not: it is not a voice and not a held note.","The returns are the chamber responding to one sound, not a signal being played.","Name the archive class for a recording that is the room''s own reply."],"narrativeObjective":"Classify the audio log by what produced it and recover the class name.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"ECHO","validationMethod":"exact","fullSolution":"The log has a single onset, no voice and no held tone, followed by the chamber''s own decaying returns. It is a room impulse response, which the archive classes as ECHO."}',
  metadata = '{"type":"AUDIO","difficulty":4,"time":"8m","storyReveal":"The audio log is not a person speaking and not a note being held. It is the room answering a single sound - an impulse response - which is why the log is filed as the room''s own reply rather than as a voice or a held tone.","locationClue":{"format":"Symbol","clueText":"LINA''S NOTE: \"The condition-mark for memory is cut in the library reading room.\"","solution":"Library Reading Room Condition-Mark","nextPhysicalLocation":"[LIBRARY] - Reading Room Fifth Symbol","nextQrNode":"QR-NODE-20","explanation":"Directs teams from the stage to the condition-mark in the library reading room."},"evidenceUnlocked":{"id":"EVID-P17","category":"Audio","title":"Reading Room Condition-Mark - Memory","state":"RECOVERED","timestamp":"Stage 3","source":"Library reading room","content":"A wooden condition-mark in the reading room. It logs MEMORY: the condition recorded for a subject whose store was held in the bank."},"whyTeamworkMatters":"Only the spectrum shows an onset with decaying returns and no voice; only the class register defines the room-reply class; only the custody field names the class.","feeds":"P16"}'
WHERE code = 'P17';

-- P17b The Echo Fold - Stage 3 (answer reframed to the single token DOORS)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Basement Archive - Folded Artefact Survey","dataPayload":"BASEMENT ARCHIVE: a folded foil log-sheet, eight panels, pressed flat. Along the creases a plan is imprinted: straight walls broken at regular points. On the outer panel an archive reading note is hand-stamped in Bureau lettering.","visualType":"observation","whatTheySee":"A folded foil sheet whose creases carry an imprinted plan and a stamped reading note.","taskPrompt":"Unfold the sheet, read the stamped note, and record what the plan shows.","intermediateOutput":"An eight-panel sheet; an imprinted plan of broken walls; a stamped note."},"analyst":{"role":"ANALYST","screenTitle":"Archive Reading Note - Feature Count","dataPayload":"READING NOTE: FILE BY FEATURE, NOT BY TIME. UNFOLD AND COUNT THE OPENINGS IN THE WALL; THIS RECORD IS CLASSED BY WHAT YOU COUNT. Counting the breaks along the imprinted walls gives a set of openings, each one an opening through a wall. The record is filed by that feature, not by any time on the log.","visualType":"document-forensics","whatTheySee":"A stamped reading note instructing a count of wall openings rather than a reading of times.","taskPrompt":"Follow the note: count the wall openings and decide what feature the record is classed by.","intermediateOutput":"The record is classed by the openings in the wall, not by a time."},"operator":{"role":"OPERATOR","screenTitle":"Class Register - Feature Index","dataPayload":"CLASS REGISTER: the archive holds the record under a class named for the feature it counts. Submit that class: the plural name for the openings one passes through in a wall, not the number of them.","visualType":"meta","whatTheySee":"A class register that files the record under a class named for a counted feature.","taskPrompt":"Submit the class the record is filed under.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The class register, which files the folded record under a class named for the feature the reading note tells the team to count.","operatorTaskDescription":"Read the stamped note, count the wall openings on the unfolded plan, and submit the plural class name for those openings."},"coordinationChain":{"observerProduces":"Observer reports the folded sheet, the imprinted plan and the stamped reading note.","analystTransforms":"Analyst follows the note and identifies the counted feature as the openings in the wall.","operatorExecutes":"Operator files the record under the class named for that feature."},"hints":["The note tells you to file by a feature, not by a time on the log.","Unfold the sheet and count the regular breaks along the imprinted walls.","Name, in the plural, the openings you would pass through in that wall."],"narrativeObjective":"Classify the folded record by the feature its own reading note tells the team to count.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"DOORS","validationMethod":"exact","fullSolution":"The artefact''s own reading note files it by a counted feature, not by a time. The counted feature is the openings in the wall, and the class the register uses for those openings is DOORS."}',
  metadata = '{"type":"CIPHER","difficulty":4,"time":"8m","storyReveal":"The folded sheet carries no riddle and no transcript. Its own reading note files it by a counted feature, not by a time, and the count names the class. The basement record was classified by the room, not by the clock.","locationClue":{"format":"Symbol","clueText":"LINA''S NOTE: \"The reading room holds the next condition-mark. Seek it where the shelves turn.\"","solution":"Library Reading Room Condition-Mark","nextPhysicalLocation":"[LIBRARY] - Reading Room Fifth Symbol","nextQrNode":"QR-NODE-20","explanation":"Directs teams from the basement archive to the condition-mark in the reading room."},"evidenceUnlocked":{"id":"EVID-P17b","category":"Document","title":"Basement Archive Folded Log-Sheet","state":"RECOVERED","timestamp":"Stage 3","source":"Basement archive folded sheet","content":"The folded foil log-sheet, creased into eight panels and stamped with a reading note: file by feature, not by time. The imprinted wall plan carries a countable set of openings."},"whyTeamworkMatters":"Only the sheet shows the folds and imprinted walls; only the reading note says what to count; only the class register names the class.","feeds":"P17"}'
WHERE code = 'P17b';

-- P18 The Pattern Lock - Stage 3
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Pattern Lock - Cabinet Inspection","dataPayload":"READING ROOM CABINET: a records cabinet with four numbered drums along its top edge, not a keypad and not a grid. Around the lock plate the seven condition-marks are inlaid. The drums are indexed to a charge-out reference, and the cabinet shows shelf wear only at one drum.","visualType":"observation","whatTheySee":"A filing cabinet whose four drums index a charge-out reference, ringed by the seven condition-marks.","taskPrompt":"Record the lock type and what the drums appear to index.","intermediateOutput":"Four drums indexing a charge-out reference, not a keypad."},"analyst":{"role":"ANALYST","screenTitle":"Reading Room Holdings Schedule","dataPayload":"CABINET SCHEDULE: the reading room holdings schedule shows the cabinet accepts a filing reference, not a combination and not a code word. The file pulled for this room was charged out under the Bureau case-file address, and the schedule records that address in the archive''s own notation.","visualType":"document-forensics","whatTheySee":"A holdings schedule showing the cabinet takes a filing reference rather than a combination.","taskPrompt":"Decide from the schedule what the cabinet actually accepts and where the address is recorded.","intermediateOutput":"The cabinet accepts a case-file reference, recorded in archive notation."},"operator":{"role":"OPERATOR","screenTitle":"Charge-Out Record","dataPayload":"CHARGE-OUT RECORD: the case file was pulled to this reading room. Its address, in the archive''s own notation, is BINDER THIRTY-FOUR, SHELF TWO, FILE FIVE. Submit the case-file reference the drums expect.","visualType":"meta","whatTheySee":"A charge-out record naming the pulled case file by its archive address.","taskPrompt":"Submit the case-file reference the drums expect.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The charge-out record, which names the pulled case file by its archive address and shows the cabinet was keyed to that reference.","operatorTaskDescription":"Compose the case-file reference from the binder, shelf and file on the charge-out record and submit it."},"coordinationChain":{"observerProduces":"Observer reports four drums indexing a charge-out reference on a filing cabinet.","analystTransforms":"Analyst shows the cabinet accepts a filing reference, not a combination or a code word.","operatorExecutes":"Operator composes the reference from the charge-out record and submits it."},"hints":["This is a filing cabinet, so ask what a filing cabinet would accept.","A combination or a code word would not be filed in a holdings schedule.","Compose the case-file reference from the binder, shelf and file named in the charge-out record."],"narrativeObjective":"Classify the reading-room lock as an archive cabinet and recover its reference.","roleDependencyLevel":"D2"}',
  answer_metadata = '{"acceptedAnswer":"3425","validationMethod":"exact","fullSolution":"The cabinet is a records cabinet whose drums index a filing reference rather than a combination. The charge-out record names the case-file address, which composes to the reference 3425."}',
  metadata = '{"type":"PATTERN","difficulty":3,"time":"6m","storyReveal":"The reading-room lock is a filing cabinet. It never wanted a combination or a code word; it wanted the case-file reference, the same file the Bureau has pulled throughout. The lock is custody, not cryptography.","locationClue":{"format":"Symbol","clueText":"LINA''S NOTE: \"The garden keeps the next condition-mark. Walk it at dusk.\"","solution":"Campus Sculpture Garden","nextPhysicalLocation":"[CAMPUS] - Sculpture Garden","nextQrNode":"QR-NODE-21","explanation":"Directs teams from the reading room to the campus sculpture garden."},"evidenceUnlocked":{"id":"EVID-P18","category":"Visual","title":"Reading Room Condition-Mark - Choice","state":"RECOVERED","timestamp":"Stage 3","source":"Reading room cabinet plate","content":"A condition-mark inlaid around the cabinet lock plate. It logs CHOICE: the condition recorded for a subject who was selected rather than merely held."},"whyTeamworkMatters":"Only the cabinet shows four drums and the conditions inlaid; only the schedule shows it takes a filing reference; only the charge-out record names the reference.","feeds":"P17"}'
WHERE code = 'P18';

-- P19 The Archive - Stage 3
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Sculpture Garden - Marker Survey","dataPayload":"SCULPTURE GARDEN: a low bronze marker set flush to the ground at the edge of the pond. Its face carries a survey tag and an EMPTY dedication plate. The plinth sits half below the water line and stands well under the path level.","visualType":"observation","whatTheySee":"A flush bronze marker with a survey tag, an empty dedication plate and a half-covering water line.","taskPrompt":"Record the plate, the tag and the water line.","intermediateOutput":"Survey tag, empty dedication plate, marker half below the water line."},"analyst":{"role":"ANALYST","screenTitle":"Campus Survey Register","dataPayload":"CAMPUS SURVEY REGISTER: the register lists every garden object by class. This grid cell object has no dedication, so it is not a memorial, and no commission entry, so it is not public art. It is listed as a survey marker, named by the condition it marks: the condition of being placed beneath the water line.","visualType":"document-forensics","whatTheySee":"A survey register that classes the marker and rules out memorial and public-art entries.","taskPrompt":"Use the register to decide what the object is, and what condition it is named for.","intermediateOutput":"A survey marker named for the condition of lying below the water line."},"operator":{"role":"OPERATOR","screenTitle":"Estates Accessions Register","dataPayload":"ESTATES ACCESSIONS: the marker is accessioned by name, not by artist or donor. Submit the survey name: the condition of being held below the surface.","visualType":"meta","whatTheySee":"An estates register that accessions the marker by its survey name.","taskPrompt":"Submit the survey name by which the marker is accessioned.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The estates accessions register, which rules out artist and donor and accessions the garden marker by a survey name.","operatorTaskDescription":"Match the survey register class (a marker, not a memorial or an artwork) with the estates accession, and submit the survey name."},"coordinationChain":{"observerProduces":"Observer reports a flush marker with an empty dedication plate, a survey tag and a half-covering water line.","analystTransforms":"Analyst shows the register classes it as a survey marker named for the condition of lying below water.","operatorExecutes":"Operator submits the survey name recorded in the estates accessions register."},"hints":["Decide first what the object is not: it has no dedication and no artist.","A survey marker is named for the condition it marks, not for a person.","Give the condition of being placed and held beneath the water line."],"narrativeObjective":"Classify the garden object and recover the survey name it is accessioned under.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"SUBMERGE","validationMethod":"exact","fullSolution":"No dedication and no commission rule out a memorial and public art, so the object is a survey marker. The register names it for the condition of lying beneath the water line, which is SUBMERGE."}',
  metadata = '{"type":"DEDUCTION","difficulty":4,"time":"7m","storyReveal":"The garden object is neither public art nor a memorial: no commission and no dedication. It is a survey marker, accessioned by name, named for the condition of lying beneath the water line.","locationClue":{"format":"Symbol","clueText":"LINA''S NOTE: \"The last condition-mark rests on the Admin Building dome. Look up from the courtyard.\"","solution":"Admin Building Dome","nextPhysicalLocation":"[ADMIN BUILDING] - Building Dome","nextQrNode":"QR-NODE-22","explanation":"Directs teams from the sculpture garden to the Admin Building dome."},"evidenceUnlocked":{"id":"EVID-P19","category":"Document","title":"Campus Survey Marker - Truth","state":"RECOVERED","timestamp":"Stage 3","source":"Sculpture garden pond edge","content":"A survey register entry for the garden marker. It confirms the object is a survey marker, named for the condition of being placed beneath the water line, and rules out a memorial or a public artwork."},"whyTeamworkMatters":"Only the marker shows the empty plate and the water line; only the survey register classes it and names the condition; only the accessions register confirms the name.","feeds":"P18"}'
