-- P20 The Symbol Sequence - Stage 3
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Dome Panel - Condition-Mark Survey","dataPayload":"DOME PANEL: seven condition-marks in a fixed row on the underside of the dome, each with a small subject tally cut beneath it. The marks run in a set order that is neither alphabetical nor by size. The panel is underlit and undamaged.","visualType":"observation","whatTheySee":"Seven condition-marks in a fixed order, each with a subject tally beneath it.","taskPrompt":"Record the marks in the order shown, with their tallies.","intermediateOutput":"Seven marks in a fixed order, each with a subject tally."},"analyst":{"role":"ANALYST","screenTitle":"Subject Register - Order Cross-Reference","dataPayload":"SUBJECT REGISTER: the register lists the subjects in the programme''s own order. Read the panel against the register and the panel repeats the register order mark for mark: the glyph order IS the subject order. This is an ordered classification, not a cipher and not a date; there is no substitution alphabet and no calendar form.","visualType":"document-forensics","whatTheySee":"A subject register whose order matches the panel order mark for mark.","taskPrompt":"Cross-reference the panel order against the subject register and say what the order encodes.","intermediateOutput":"The mark order encodes the subject order; it is a classification, not a cipher or a date."},"operator":{"role":"OPERATOR","screenTitle":"Dome Panel Accession Stamp","dataPayload":"ACCESSION STAMP: the dome panel is accessioned in the archive''s own notation: BINDER TWENTY-ONE, SHELF FOUR, FILE SEVEN. Submit the four-figure reference the stamp names.","visualType":"meta","whatTheySee":"An accession stamp naming the dome panel by an archive address in heavy lettering.","taskPrompt":"Submit the four-figure reference the accession stamp names.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The dome panel accession stamp, which files the panel under an archive address written in the archive''s own notation.","operatorTaskDescription":"Compose the four-figure reference from the binder, shelf and file on the stamp, and submit it."},"coordinationChain":{"observerProduces":"Observer reports the seven marks in their fixed order with their subject tallies.","analystTransforms":"Analyst shows the mark order repeats the subject register order as an ordered classification.","operatorExecutes":"Operator composes the four-figure reference from the accession stamp and submits it."},"hints":["Decide first what the panel is not: there is no substitution alphabet and no calendar form.","Read the mark order against the subject register rather than against an alphabet.","The accession stamp carries a binder, a shelf and a file; compose the four-figure reference."],"narrativeObjective":"Classify the dome panel as an ordered classification and recover the reference on its stamp.","roleDependencyLevel":"D4"}',
  answer_metadata = '{"acceptedAnswer":"2147","validationMethod":"exact","fullSolution":"The panel is an ordered classification, not a cipher or a date, and its mark order is the subject register order. The accession stamp names a four-figure archive address, which composes to the reference 2147."}',
  metadata = '{"type":"PATTERN","difficulty":5,"time":"10m","storyReveal":"The dome panel is an ordered classification, not a cipher sequence and not a date. Its mark order is the subject order, and its accession stamp files it as a record. The seven conditions are the programme''s own log of how each subject was held.","locationClue":{"format":"Path Instruction","clueText":"LINA''S NOTE: \"Return to the Admin Building main doors. The fourth floor window has a view.\"","solution":"Admin Building Fourth Floor Window","nextPhysicalLocation":"[ADMIN BUILDING] - Fourth Floor Window","nextQrNode":"QR-NODE-23","explanation":"Directs teams from the dome to the fourth floor window."},"evidenceUnlocked":{"id":"EVID-P20","category":"Visual","title":"Dome Panel Condition-Marks - Finality","state":"RECOVERED","timestamp":"Stage 3","source":"Admin Building dome","content":"The dome panel of seven condition-marks in subject order, the last of them FINALITY: the condition recorded when a subject was closed out of the programme. The panel is accessioned by an archive address."},"whyTeamworkMatters":"Only the panel shows the mark order; only the subject register fixes the order as the subject order; only the accession stamp files the panel.","feeds":"P19"}'
