-- M03 The Symbol Meta - Stage 3
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Stage 3 - Exhibit Aggregate","dataPayload":"STAGE 3 AGGREGATE: the seven stage-3 exhibits are laid out in discovery order. Each carries one of the seven condition-marks: the memory-bank index, the wall dial, the seating roll, the room record, the folded basement sheet, the cabinet schedule, the garden marker and the dome panel. Every mark names a condition a subject was held under.","visualType":"meta","whatTheySee":"Seven stage-3 exhibits, each bearing one of the seven condition-marks.","taskPrompt":"Read the exhibits against the seven marks and report the mapping.","intermediateOutput":"Seven exhibits, seven marks, each mark naming a condition of holding."},"analyst":{"role":"ANALYST","screenTitle":"Classification Synthesis","dataPayload":"SYNTHESIS: the seven marks encode no value. Each mark stands for a containment condition - origin, connection, structure, memory, choice, truth, finality - the conditions the programme logged for each subject. The archive uses two kinds of mark: one that points to a value, and one that stands for a condition in itself. The seven are all of the second kind.","visualType":"document-forensics","whatTheySee":"A synthesis showing the seven marks stand for containment conditions rather than encoding values.","taskPrompt":"Name the kind of mark the seven are: one that stands for a condition rather than encoding a value.","intermediateOutput":"The seven marks stand for conditions; they are of the kind that means rather than encodes."},"operator":{"role":"OPERATOR","screenTitle":"Records Taxonomy Register","dataPayload":"TAXONOMY REGISTER: the Bureau records taxonomy records that kind of mark by its name. Submit the class name for a mark that stands for a condition rather than encoding a value.","visualType":"meta","whatTheySee":"A taxonomy register that classes marks as pointer or as standing-for.","taskPrompt":"Submit the class name the taxonomy gives this kind of mark.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The records taxonomy register, which classes every mark as either a pointer to a value or a mark that stands for a condition in itself.","operatorTaskDescription":"Combine the exhibit mapping with the synthesis, and submit the taxonomy class name for a mark that stands for a condition."},"coordinationChain":{"observerProduces":"Observer maps the seven stage-3 exhibits onto the seven condition-marks.","analystTransforms":"Analyst shows the marks stand for containment conditions rather than encoding values.","operatorExecutes":"Operator submits the taxonomy class for a mark that stands for a condition."},"hints":["Ask whether the seven marks encode a value or stand for something in themselves.","Each mark names a condition a subject was held under, not a number to be substituted.","Name the taxonomy class for a mark that means a condition rather than encodes one."],"narrativeObjective":"Unify the seven stage-3 exhibits and name the kind of mark the glyphs actually are.","roleDependencyLevel":"D5"}',
  answer_metadata = '{"acceptedAnswer":"SYMBOL","validationMethod":"exact","fullSolution":"The seven marks encode no values; each stands for a containment condition the programme logged for a subject. The taxonomy class for a mark that stands for a condition rather than encoding one is SYMBOL."}',
  metadata = '{"type":"META","difficulty":5,"time":"18m","storyReveal":"The seven marks are not a code. They are a containment classification: the conditions the programme logged for each subject - origin, connection, structure, memory, choice, truth, finality. The glyphs classify how a subject was held, which is why they recur wherever a subject was recorded.","locationClue":{"format":"Marker","clueText":"LINA''S NOTE: \"Return to the rooftop spire. The last stage begins.\"","solution":"Rooftop Spire","nextPhysicalLocation":"[ROOFTOP] - Transmitter Spire","nextQrNode":"QR-NODE-24","explanation":"Points to the rooftop spire for Stage 5."},"evidenceUnlocked":{"id":"EVID-M03","category":"Document","title":"Stage 3 Meta - Containment Taxonomy","state":"RECOVERED","timestamp":"Stage 3","source":"Central records office terminal","content":"The records taxonomy entry for the seven marks: each is a containment classification, standing for the condition a subject was held under, not a code and not a value. The taxonomy names this kind of mark by class."},"whyTeamworkMatters":"Only the exhibits show each mark on a real record; only the synthesis shows the marks stand for conditions; only the taxonomy register names the class.","feeds":"P14 P15 P16 P17 P18 P19 P20 P21"}'
